'use client';

import Link from 'next/link';
import { FormEvent, useEffect, useState } from 'react';
import { api } from '@/lib/api';

type Community = { slug: string; name: string; parent: { name: string } | null };
type Mode = 'event' | 'poll';

export default function CreateEventPage() {
  const [communities, setCommunities] = useState<Community[]>([]);
  const [mode, setMode] = useState<Mode>('event');
  const [error, setError] = useState(''); const [message, setMessage] = useState('');
  useEffect(() => { api<Community[]>('/communities').then(setCommunities).catch((cause) => setError(cause.message)); }, []);

  async function submitEvent(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget); setError(''); setMessage('');
    const capacity = String(form.get('capacity') || '').trim();
    try { const result = await api<{ id: string }>('/events', { method: 'POST', body: JSON.stringify({ communitySlug: form.get('communitySlug'), title: form.get('title'), description: form.get('description'), format: form.get('format'), startsAt: new Date(String(form.get('startsAt'))).toISOString(), endsAt: form.get('endsAt') ? new Date(String(form.get('endsAt'))).toISOString() : undefined, location: form.get('location') || undefined, capacity: capacity ? Number(capacity) : undefined, publish: form.get('publish') === 'on' }) }); setMessage(`Событие сохранено. Открыть: /events/${result.id}`); event.currentTarget.reset(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось создать событие'); }
  }

  async function submitPoll(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget); setError(''); setMessage('');
    const quorum = String(form.get('quorum') || '').trim();
    try { await api(`/governance/communities/${form.get('communitySlug')}/polls`, { method: 'POST', body: JSON.stringify({ title: form.get('title'), description: form.get('description'), kind: form.get('kind'), options: String(form.get('options')).split('\n').map((item) => item.trim()).filter(Boolean), closesAt: new Date(String(form.get('closesAt'))).toISOString(), quorum: quorum ? Number(quorum) : undefined, minAccountAgeDays: Number(form.get('minAccountAgeDays')), requireSubscription: form.get('requireSubscription') === 'on', allowAdvisory: form.get('allowAdvisory') === 'on' }) }); setMessage('Голосование опубликовано.'); event.currentTarget.reset(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось создать голосование'); }
  }

  return <div className="narrow-page"><p><Link className="muted" href="/events">← События и решения</Link></p><section className="card"><span className="eyebrow">Для команды сообщества</span><h1>Создать</h1><p className="muted">Выберите один сценарий. Формы не смешиваются, чтобы случайно не опубликовать голосование вместо встречи.</p><div className="segmented-control"><button type="button" className={mode === 'event' ? 'active' : ''} onClick={() => setMode('event')}>Событие</button><button type="button" className={mode === 'poll' ? 'active' : ''} onClick={() => setMode('poll')}>Голосование</button></div>{message && <div className="success-box">{message}</div>}{error && <div className="error-box">{error}</div>}
    {mode === 'event' ? <form onSubmit={submitEvent}><label>Сообщество<select name="communitySlug" required><option value="">Выберите</option>{communities.map((item) => <option key={item.slug} value={item.slug}>{item.parent ? `${item.parent.name} → ` : ''}{item.name}</option>)}</select></label><label>Название<input name="title" minLength={5} maxLength={160} required/></label><label>Описание<textarea name="description" minLength={20} maxLength={5000} required/></label><label>Формат<select name="format" defaultValue="ONLINE"><option value="ONLINE">Онлайн</option><option value="OFFLINE">Офлайн</option><option value="HYBRID">Гибрид</option></select></label><div className="form-grid-two"><label>Начало<span className="date-input-wrap"><input name="startsAt" type="datetime-local" required/></span></label><label>Окончание — необязательно<span className="date-input-wrap"><input name="endsAt" type="datetime-local"/></span></label></div><label>Место или ссылка<input name="location" maxLength={240}/></label><label>Лимит участников — необязательно<input name="capacity" type="number" min="2" max="100000"/></label><label className="form-check"><input className="form-check-input" type="checkbox" name="publish" defaultChecked/><span className="form-check-label">Сразу опубликовать и уведомить подписчиков</span></label><button className="button">Сохранить событие</button></form> : <form onSubmit={submitPoll}><label>Сообщество<select name="communitySlug" required><option value="">Выберите</option>{communities.map((item) => <option key={item.slug} value={item.slug}>{item.parent ? `${item.parent.name} → ` : ''}{item.name}</option>)}</select></label><label>Тип решения<select name="kind" defaultValue="GENERAL"><option value="GENERAL">Общий вопрос</option><option value="TEAM_REVIEW">Оценка команды</option><option value="ELECTION">Выборы</option><option value="STRUCTURE">Структура</option><option value="BUDGET">Средства сообщества</option></select></label><label>Вопрос<input name="title" minLength={5} maxLength={160} required/></label><label>Контекст<textarea name="description" minLength={10} maxLength={3000} required/></label><label>Варианты — каждый с новой строки<textarea name="options" minLength={3} maxLength={2000} required placeholder={'Поддержать\nДоработать\nОтклонить'}/></label><div className="form-grid-two"><label>Закрыть<span className="date-input-wrap"><input name="closesAt" type="datetime-local" required/></span></label><label>Кворум решающих голосов<input name="quorum" type="number" min="1" placeholder="Необязательно"/></label></div><label>Минимальный возраст аккаунта<input name="minAccountAgeDays" type="number" min="0" max="365" defaultValue="14" required/></label><label className="form-check"><input className="form-check-input" type="checkbox" name="requireSubscription" defaultChecked/><span className="form-check-label">Для решающего голоса нужна подписка на сообщество</span></label><label className="form-check"><input className="form-check-input" type="checkbox" name="allowAdvisory" defaultChecked/><span className="form-check-label">Принимать консультативные голоса новичков</span></label><button className="button">Опубликовать голосование</button></form>}</section></div>;
}
